import re
from collections import defaultdict

REPO = "/bench/repo"
INTERNAL = os.path.join(REPO, "internal")

# Parse func declarations: func (recv) Name( or func Name(
FUNC_RE = re.compile(
    r'^func\s+(?:\(([^)]*)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(',
    re.MULTILINE
)
PACKAGE_RE = re.compile(r'^package\s+(\w+)', re.MULTILINE)

def read_go_files(root):
    files = []
    for dirpath, _, filenames in os.walk(root):
        for fn in filenames:
            if fn.endswith('.go') and not fn.endswith('_test.go'):
                files.append(os.path.join(dirpath, fn))
    return files

def get_package(content):
