    for m in FUNC_RE.finditer(content):
        recv = m.group(1)
        name = m.group(2)
        # skip test helpers maybe - but we're excluding _test.go
        key = (rel, name, recv or "")
        symbols[key] = {
            'path': fpath,
            'rel_dir': rel,
            'package': pkg,
            'name': name,
            'recv': recv or "",
            'exported': name[0].isupper() if name else False,
        }

print(f"Found {len(symbols)} functions/methods in internal/")

# Read ALL go files in repo for call counting
all_files = []
for dirpath, _, filenames in os.walk(REPO):
    # skip .git
    if '.git' in dirpath.split(os.sep):
        continue
    for fn in filenames:
        if fn.endswith('.go'):
