call_counts = defaultdict(int)

# Pre-load all file contents
file_contents = {}
for fpath in all_files:
    with open(fpath) as f:
        file_contents[fpath] = f.read()

IMPORT_RE = re.compile(r'^\s*(?:[\w.]+\s+)?"([^"]+)"', re.MULTILINE)
IMPORT_ALIAS_RE = re.compile(r'^\s*(\w+)\s+"([^"]+)"', re.MULTILINE)

