    for fpath, content in file_contents.items():
        caller_rel = os.path.relpath(os.path.dirname(fpath), REPO)
        if caller_rel != rel_dir:
            continue
        count = len(pattern.findall(content))
        if count > 0 and fpath == sym['path']:
            def_pattern = re.compile(r'^func\s+' + re.escape(name) + r'\s*\(', re.MULTILINE)
            if def_pattern.search(content):
                count -= 1
        call_counts[(rel_dir, name, recv)] += max(0, count)

# Sort by count
sorted_syms = sorted(call_counts.items(), key=lambda x: -x[1])
print("\nTop 30 by fan-in:")
