perl << 'PERLEOF'
use strict;
use warnings;
use File::Find;
use File::Basename;

my $REPO = "/bench/repo";
my $INTERNAL = "$REPO/internal";

# Read module name
open my $gm, '<', "$REPO/go.mod" or die $!;
my $module;
while (<$gm>) { if (/^module\s+(\S+)/) { $module = $1; last; } }
close $gm;
print "Module: $module\n";

my @all_go_files;
find(sub {
    return unless /\.go$/;
    return if $File::Find::dir =~ m{/\.git};
    push @all_go_files, $File::Find::name;
}, $REPO);

my @internal_go_files = grep { $_ =~ m{^$INTERNAL/} && $_ !~ /_test\.go$/ } @all_go_files;

# symbols: key = "rel_dir|name|recv" -> {path, package, name, recv, exported}
my %symbols;

for my $fpath (@internal_go_files) {
    open my $fh, '<', $fpath or next;
    my $content = do { local $/; <$fh> };
    close $fh;
    my ($pkg) = $content =~ /^package\s+(\w+)/m;
    next unless $pkg;
    my $rel = $fpath;
    $rel =~ s/^\Q$REPO\E\/?//;
    my $rel_dir = $rel;
    $rel_dir =~ s/\/[^\/]+$//;

    while ($content =~ /^func\s+(?:\(([^)]*)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(/gm) {
        my ($recv, $name) = ($1 // '', $2);
        my $key = "$rel_dir|$name|$recv";
        $symbols{$key} = {
            path => $fpath,
            rel_dir => $rel_dir,
            package => $pkg,
            name => $name,
            recv => $recv,
            exported => ($name =~ /^[A-Z]/),
        };
    }
}
print "Found ", scalar(keys %symbols), " functions/methods in internal/\n";

# Load all file contents
my %file_contents;
my %file_pkg;
my %file_rel_dir;
for my $fpath (@all_go_files) {
    open my $fh, '<', $fpath or next;
    my $content = do { local $/; <$fh> };
    close $fh;
    $file_contents{$fpath} = $content;
    my ($pkg) = $content =~ /^package\s+(\w+)/m;
    $file_pkg{$fpath} = $pkg // '';
    my $rel = $fpath;
    $rel =~ s/^\Q$REPO\E\/?//;
    my $rel_dir = $rel;
    $rel_dir =~ s/\/[^\/]+$//;
    $file_rel_dir{$fpath} = $rel_dir;
}

my %call_counts;

sub count_matches {
    my ($content, $pattern) = @_;
    my $count = 0;
    while ($content =~ /$pattern/g) { $count++; }
    return $count;
}

# Build import map per file
sub get_import_map {
    my ($content) = @_;
    my %import_map;
    my $in_import = 0;
    for my $line (split /\n/, $content) {
        if ($line =~ /^import\s*\(/) { $in_import = 1; next; }
        if ($in_import && $line =~ /^\)/) { $in_import = 0; next; }
        if ($line =~ /^import\s+"([^"]+)"/) {
            my $imp = $1;
            if ($imp =~ /^\Q$module\E\/internal\/(.+)$/) {
                my $rel = "internal/$1";
                my $alias = basename($rel);
                $import_map{$alias} = $rel;
            }
            next;
        }
        if ($in_import && $line =~ /^\s*(?:(\w+)\s+)?"([^"]+)"/) {
            my ($alias, $imp) = ($1, $2);
            if ($imp =~ /^\Q$module\E\/internal\/(.+)$/) {
                my $rel = "internal/$1";
                $alias //= basename($rel);
                $import_map{$alias} = $rel;
            }
        }
    }
    return %import_map;
}

# Exported non-method functions
for my $key (keys %symbols) {
    my $sym = $symbols{$key};
    next unless $sym->{exported} && !$sym->{recv};

    for my $fpath (keys %file_contents) {
        my $content = $file_contents{$fpath};
        my %import_map = get_import_map($content);
        my @aliases = grep { $import_map{$_} eq $sym->{rel_dir} } keys %import_map;
        if (!@aliases && $file_rel_dir{$fpath} eq $sym->{rel_dir}) {
            @aliases = ('__SAME__');
        }
        next unless @aliases;

        my $count = 0;
        for my $alias (@aliases) {
            if ($alias eq '__SAME__') {
                $count += count_matches($content, qr/\b\Q$sym->{name}\E\s*\(/);
            } else {
                $count += count_matches($content, qr/\b\Q$alias\E\.\Q$sym->{name}\E\s*\(/);
            }
        }
        if ($count > 0 && $fpath eq $sym->{path}) {
            $count-- if $content =~ /^func\s+(?:\([^)]*\)\s+)?\Q$sym->{name}\E\s*\(/m;
        }
        $call_counts{$key} += $count if $count > 0;
    }
}

# Methods
for my $key (keys %symbols) {
    my $sym = $symbols{$key};
    next unless $sym->{recv};

    for my $fpath (keys %file_contents) {
        my $content = $file_contents{$fpath};
        my $count = count_matches($content, qr/\.\Q$sym->{name}\E\s*\(/);
        if ($count > 0 && $fpath eq $sym->{path}) {
            my $defs = () = $content =~ /^func\s+\([^)]*\)\s+\Q$sym->{name}\E\s*\(/gm;
            $count -= $defs;
        }
        $call_counts{$key} += $count if $count > 0;
    }
}

# Unexported non-method
for my $key (keys %symbols) {
    my $sym = $symbols{$key};
    next if $sym->{exported} || $sym->{recv};

    for my $fpath (keys %file_contents) {
        next unless $file_rel_dir{$fpath} eq $sym->{rel_dir};
        my $content = $file_contents{$fpath};
        my $count = count_matches($content, qr/\b\Q$sym->{name}\E\s*\(/);
        if ($count > 0 && $fpath eq $sym->{path}) {
            $count-- if $content =~ /^func\s+\Q$sym->{name}\E\s*\(/m;
        }
        $call_counts{$key} += $count if $count > 0;
    }
}

my @sorted = sort { $call_counts{$b} <=> $call_counts{$a} } keys %call_counts;
print "\nTop 30 by fan-in:\n";
for my $i (0..29) {
    last unless $i < @sorted;
    my $key = $sorted[$i];
    my $sym = $symbols{$key};
    my $recv = $sym->{recv} ? " ($sym->{recv})" : "";
    printf "%4d  %s%s  %s\n", $call_counts{$key}, $sym->{name}, $recv, $sym->{path};
}
PERLEOF

